# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe "Api::V1::Invoices::BulkDeletion#create billing fence", type: :request do
  # "Every invoice, line-item, invoice-tax and payment write, mobile-collection payments included,
  # gets 503 ownership_moving while handoff_step is set and writes nothing"
  it "answers bulk deletion of three invoices with 503 ownership_moving and removes none of them or their children during a handoff" do
    company = create(:company)
    client = create(:client, company:)
    user = create(:user, current_workspace_id: company.id)
    create(:employment, company:, user:)
    user.add_role :admin, company
    sign_in user
    invoices = create_list(:invoice, 3, company:, client:)
    invoices.each do |invoice|
      create(:invoice_line_item, invoice:)
      create(:invoice_tax, invoice:)
    end
    expect([Invoice.count, InvoiceLineItem.count, InvoiceTax.count]).to eq([3, 3, 3])
    TimekeepingOwnership.current.update!(handoff_step: "close_admission")

    send_request :post, api_v1_invoices_bulk_deletion_index_path,
      params: { invoices_ids: invoices.map(&:id) },
      headers: auth_headers(user)

    expect(response).to have_http_status(:service_unavailable)
    expect(json_response["reason"]).to eq("ownership_moving")
    expect([Invoice.count, InvoiceLineItem.count, InvoiceTax.count]).to eq([3, 3, 3])
  end
end

require "rails_helper"

RSpec.describe "Api::V1::Invoices::BulkDeletion#create inside one fenced transaction", type: :request do
  # "With no handoff the behaviour is unchanged."
  # Running every destroy in one shared transaction must not let a refused destroy commit the
  # line-item and tax deletions that run before the payment check.
  it "keeps a paid invoice whole with its line items taxes and totals when a mixed bulk deletion runs with no handoff" do
    company = create(:company)
    client = create(:client, company:)
    user = create(:user, current_workspace_id: company.id)
    create(:employment, company:, user:)
    user.add_role :admin, company
    sign_in user
    deletable = create(:invoice, company:, client:)
    paid = create(:invoice, company:, client:, amount_due: 300)
    line_item = create(:invoice_line_item, invoice: paid)
    tax = create(:invoice_tax, invoice: paid)
    create(:payment, invoice: paid, amount: 300)
    money_before = paid.reload.attributes.slice("amount", "tax", "discount", "outstanding_amount")

    send_request :post, api_v1_invoices_bulk_deletion_index_path,
      params: { invoices_ids: [deletable.id, paid.id] },
      headers: auth_headers(user)

    expect(response).to have_http_status(:unprocessable_content)
    expect(json_response["undeletable_invoice_ids"]).to eq([paid.id])
    expect(Invoice.exists?(deletable.id)).to be(false)
    expect(InvoiceLineItem.exists?(line_item.id)).to be(true)
    expect(InvoiceTax.exists?(tax.id)).to be(true)
    expect(paid.reload.attributes.slice("amount", "tax", "discount", "outstanding_amount")).to eq(money_before)
  end
end
